use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum TokenKind {
    // Structural tokens generated by Python's off-side rule
    Indent,
    Dedent,
    Newline,

    // Keywords
    Def,
    Class,
    Async,
    Await,
    Return,
    Yield,
    If,
    Elif,
    Else,
    While,
    For,
    In,
    Try,
    Except,
    Finally,
    With,
    As,
    Import,
    From,
    Match,
    Case,
    Pass,
    Break,
    Continue,
    Raise,
    Assert,
    Global,
    Nonlocal,
    Lambda,

    // Literals & Identifiers
    Identifier(String),
    StringLiteral(String),
    IntLiteral(i64),
    FloatLiteral(String),
    True,
    False,
    None,

    // Punctuation & Delimiters
    LParen,
    RParen,
    LBracket,
    RBracket,
    LBrace,
    RBrace,
    Colon,
    Comma,
    Dot,
    Arrow, // ->
    At,    // @ decorator

    // Operators
    Assign,
    Plus,
    Minus,
    Star,
    Slash,
    DoubleSlash,
    Percent,
    DoubleStar,
    Eq,
    NotEq,
    Lt,
    LtEq,
    Gt,
    GtEq,
    Walrus, // :=

    // Comment
    Comment(String),

    // End of file
    Eof,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Token {
    pub kind: TokenKind,
    pub start: usize,
    pub end: usize,
    pub line: usize,
    pub column: usize,
}

/// Replicates PyCharm's `PythonIndentingLexer`.
/// Processes raw text into tokens, handling whitespace indentation levels,
/// bracket nesting depth, and generating synthetic `Indent` and `Dedent` tokens.
pub struct PythonIndentingLexer<'a> {
    chars: Vec<char>,
    pos: usize,
    line: usize,
    column: usize,
    indent_stack: Vec<usize>,
    paren_depth: usize,
    at_line_start: bool,
    pending_tokens: Vec<Token>,
    _lifetime: std::marker::PhantomData<&'a str>,
}

impl<'a> PythonIndentingLexer<'a> {
    pub fn new(source: &'a str) -> Self {
        Self {
            chars: source.chars().collect(),
            pos: 0,
            line: 1,
            column: 0,
            indent_stack: vec![0],
            paren_depth: 0,
            at_line_start: true,
            pending_tokens: Vec::new(),
            _lifetime: std::marker::PhantomData,
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn peek_next(&self) -> Option<char> {
        self.chars.get(self.pos + 1).copied()
    }

    fn advance(&mut self) -> Option<char> {
        if let Some(&ch) = self.chars.get(self.pos) {
            self.pos += 1;
            if ch == '\n' {
                self.line += 1;
                self.column = 0;
            } else {
                self.column += 1;
            }
            Some(ch)
        } else {
            None
        }
    }

    /// Tokenizes the entire source string into a stream of tokens.
    pub fn tokenize_all(&mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        loop {
            let tok = self.next_token();
            let is_eof = tok.kind == TokenKind::Eof;
            tokens.push(tok);
            if is_eof {
                break;
            }
        }
        tokens
    }

    /// Read next token from the stream
    pub fn next_token(&mut self) -> Token {
        if !self.pending_tokens.is_empty() {
            return self.pending_tokens.remove(0);
        }

        if self.at_line_start {
            self.handle_indentation();
            if !self.pending_tokens.is_empty() {
                return self.pending_tokens.remove(0);
            }
        }

        self.skip_whitespace_and_continuations();

        let start = self.pos;
        let line = self.line;
        let col = self.column;

        let ch = match self.peek() {
            Some(c) => c,
            None => {
                // At EOF, unwind any remaining indent levels
                while self.indent_stack.len() > 1 {
                    self.indent_stack.pop();
                    self.pending_tokens.push(Token {
                        kind: TokenKind::Dedent,
                        start: self.pos,
                        end: self.pos,
                        line: self.line,
                        column: self.column,
                    });
                }
                if !self.pending_tokens.is_empty() {
                    return self.pending_tokens.remove(0);
                }
                return Token {
                    kind: TokenKind::Eof,
                    start: self.pos,
                    end: self.pos,
                    line: self.line,
                    column: self.column,
                };
            }
        };

        // Comments
        if ch == '#' {
            self.advance();
            let mut comment = String::new();
            while let Some(c) = self.peek() {
                if c == '\n' {
                    break;
                }
                comment.push(c);
                self.advance();
            }
            return Token {
                kind: TokenKind::Comment(comment),
                start,
                end: self.pos,
                line,
                column: col,
            };
        }

        // Newline
        if ch == '\n' {
            self.advance();
            if self.paren_depth == 0 {
                self.at_line_start = true;
                return Token {
                    kind: TokenKind::Newline,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            } else {
                // Inside parentheses, newlines are treated as whitespace
                return self.next_token();
            }
        }

        // String literals (handles ', ", ''', """)
        if ch == '\'' || ch == '"' {
            return self.read_string(start, line, col, ch);
        }

        // Delimiters that track bracket depth
        match ch {
            '(' => {
                self.advance();
                self.paren_depth += 1;
                return Token {
                    kind: TokenKind::LParen,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            ')' => {
                self.advance();
                self.paren_depth = self.paren_depth.saturating_sub(1);
                return Token {
                    kind: TokenKind::RParen,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            '[' => {
                self.advance();
                self.paren_depth += 1;
                return Token {
                    kind: TokenKind::LBracket,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            ']' => {
                self.advance();
                self.paren_depth = self.paren_depth.saturating_sub(1);
                return Token {
                    kind: TokenKind::RBracket,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            '{' => {
                self.advance();
                self.paren_depth += 1;
                return Token {
                    kind: TokenKind::LBrace,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            '}' => {
                self.advance();
                self.paren_depth = self.paren_depth.saturating_sub(1);
                return Token {
                    kind: TokenKind::RBrace,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            ':' => {
                self.advance();
                if self.peek() == Some('=') {
                    self.advance();
                    return Token {
                        kind: TokenKind::Walrus,
                        start,
                        end: self.pos,
                        line,
                        column: col,
                    };
                }
                return Token {
                    kind: TokenKind::Colon,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            ',' => {
                self.advance();
                return Token {
                    kind: TokenKind::Comma,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            '.' => {
                self.advance();
                return Token {
                    kind: TokenKind::Dot,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            '@' => {
                self.advance();
                return Token {
                    kind: TokenKind::At,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            '-' => {
                self.advance();
                if self.peek() == Some('>') {
                    self.advance();
                    return Token {
                        kind: TokenKind::Arrow,
                        start,
                        end: self.pos,
                        line,
                        column: col,
                    };
                }
                return Token {
                    kind: TokenKind::Minus,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            '+' => {
                self.advance();
                return Token {
                    kind: TokenKind::Plus,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            '*' => {
                self.advance();
                if self.peek() == Some('*') {
                    self.advance();
                    return Token {
                        kind: TokenKind::DoubleStar,
                        start,
                        end: self.pos,
                        line,
                        column: col,
                    };
                }
                return Token {
                    kind: TokenKind::Star,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            '/' => {
                self.advance();
                if self.peek() == Some('/') {
                    self.advance();
                    return Token {
                        kind: TokenKind::DoubleSlash,
                        start,
                        end: self.pos,
                        line,
                        column: col,
                    };
                }
                return Token {
                    kind: TokenKind::Slash,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            '%' => {
                self.advance();
                return Token {
                    kind: TokenKind::Percent,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            '=' => {
                self.advance();
                if self.peek() == Some('=') {
                    self.advance();
                    return Token {
                        kind: TokenKind::Eq,
                        start,
                        end: self.pos,
                        line,
                        column: col,
                    };
                }
                return Token {
                    kind: TokenKind::Assign,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            '!' => {
                self.advance();
                if self.peek() == Some('=') {
                    self.advance();
                    return Token {
                        kind: TokenKind::NotEq,
                        start,
                        end: self.pos,
                        line,
                        column: col,
                    };
                }
            }
            '<' => {
                self.advance();
                if self.peek() == Some('=') {
                    self.advance();
                    return Token {
                        kind: TokenKind::LtEq,
                        start,
                        end: self.pos,
                        line,
                        column: col,
                    };
                }
                return Token {
                    kind: TokenKind::Lt,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            '>' => {
                self.advance();
                if self.peek() == Some('=') {
                    self.advance();
                    return Token {
                        kind: TokenKind::GtEq,
                        start,
                        end: self.pos,
                        line,
                        column: col,
                    };
                }
                return Token {
                    kind: TokenKind::Gt,
                    start,
                    end: self.pos,
                    line,
                    column: col,
                };
            }
            _ => {}
        }

        // Numbers
        if ch.is_ascii_digit() {
            let mut num_str = String::new();
            let mut is_float = false;
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() || c == '_' {
                    if c != '_' {
                        num_str.push(c);
                    }
                    self.advance();
                } else if c == '.'
                    && !is_float
                    && self.peek_next().is_some_and(|n| n.is_ascii_digit())
                {
                    is_float = true;
                    num_str.push(c);
                    self.advance();
                } else {
                    break;
                }
            }

            let kind = if is_float {
                TokenKind::FloatLiteral(num_str)
            } else {
                TokenKind::IntLiteral(num_str.parse::<i64>().unwrap_or(0))
            };

            return Token {
                kind,
                start,
                end: self.pos,
                line,
                column: col,
            };
        }

        // Identifiers and Keywords
        if ch.is_alphabetic() || ch == '_' {
            let mut ident = String::new();
            while let Some(c) = self.peek() {
                if c.is_alphanumeric() || c == '_' {
                    ident.push(c);
                    self.advance();
                } else {
                    break;
                }
            }

            // Check for prefixed strings e.g. f"hello", r"raw", b"bytes"
            if (ident == "f" || ident == "r" || ident == "b" || ident == "u")
                && (self.peek() == Some('\'') || self.peek() == Some('"'))
            {
                let quote = self.peek().unwrap();
                return self.read_string(start, line, col, quote);
            }

            let kind = match ident.as_str() {
                "def" => TokenKind::Def,
                "class" => TokenKind::Class,
                "async" => TokenKind::Async,
                "await" => TokenKind::Await,
                "return" => TokenKind::Return,
                "yield" => TokenKind::Yield,
                "if" => TokenKind::If,
                "elif" => TokenKind::Elif,
                "else" => TokenKind::Else,
                "while" => TokenKind::While,
                "for" => TokenKind::For,
                "in" => TokenKind::In,
                "try" => TokenKind::Try,
                "except" => TokenKind::Except,
                "finally" => TokenKind::Finally,
                "with" => TokenKind::With,
                "as" => TokenKind::As,
                "import" => TokenKind::Import,
                "from" => TokenKind::From,
                "match" => TokenKind::Match,
                "case" => TokenKind::Case,
                "pass" => TokenKind::Pass,
                "break" => TokenKind::Break,
                "continue" => TokenKind::Continue,
                "raise" => TokenKind::Raise,
                "assert" => TokenKind::Assert,
                "global" => TokenKind::Global,
                "nonlocal" => TokenKind::Nonlocal,
                "lambda" => TokenKind::Lambda,
                "True" => TokenKind::True,
                "False" => TokenKind::False,
                "None" => TokenKind::None,
                _ => TokenKind::Identifier(ident),
            };

            return Token {
                kind,
                start,
                end: self.pos,
                line,
                column: col,
            };
        }

        // Catch-all
        self.advance();
        self.next_token()
    }

    fn handle_indentation(&mut self) {
        let mut indent = 0;
        let mut whitespace_len = 0;

        while let Some(c) = self.peek() {
            if c == ' ' {
                indent += 1;
                whitespace_len += 1;
                self.advance();
            } else if c == '\t' {
                indent = (indent / 8 + 1) * 8;
                whitespace_len += 1;
                self.advance();
            } else {
                break;
            }
        }

        // Empty lines or lines containing only comments do not affect indentation
        if let Some(c) = self.peek() {
            if c == '\n' || c == '#' || c == '\r' {
                return;
            }
        } else {
            return;
        }

        self.at_line_start = false;

        let current_indent = *self.indent_stack.last().unwrap_or(&0);
        if indent > current_indent {
            self.indent_stack.push(indent);
            self.pending_tokens.push(Token {
                kind: TokenKind::Indent,
                start: self.pos - whitespace_len,
                end: self.pos,
                line: self.line,
                column: 0,
            });
        } else if indent < current_indent {
            while let Some(&top) = self.indent_stack.last() {
                if top <= indent {
                    break;
                }
                self.indent_stack.pop();
                self.pending_tokens.push(Token {
                    kind: TokenKind::Dedent,
                    start: self.pos - whitespace_len,
                    end: self.pos,
                    line: self.line,
                    column: 0,
                });
            }
        }
    }

    fn skip_whitespace_and_continuations(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\r' {
                self.advance();
            } else if c == '\\' && self.peek_next() == Some('\n') {
                // Line continuation
                self.advance();
                self.advance();
            } else {
                break;
            }
        }
    }

    fn read_string(&mut self, start: usize, line: usize, col: usize, quote: char) -> Token {
        self.advance(); // consume opening quote
        let is_triple = self.peek() == Some(quote) && self.peek_next() == Some(quote);
        if is_triple {
            self.advance();
            self.advance();
        }

        let mut content = String::new();
        while let Some(c) = self.peek() {
            if c == '\\' {
                self.advance();
                if let Some(escaped) = self.advance() {
                    content.push(escaped);
                }
            } else if c == quote {
                if is_triple {
                    if self.chars.get(self.pos..self.pos + 3) == Some(&[quote, quote, quote]) {
                        self.advance();
                        self.advance();
                        self.advance();
                        break;
                    } else {
                        content.push(c);
                        self.advance();
                    }
                } else {
                    self.advance(); // closing quote
                    break;
                }
            } else {
                content.push(c);
                self.advance();
            }
        }

        Token {
            kind: TokenKind::StringLiteral(content),
            start,
            end: self.pos,
            line,
            column: col,
        }
    }
}
